import{_ as e,o,c as r,a2 as a}from"./chunks/framework.DSc8fo6x.js";const m=JSON.parse('{"title":"If something goes wrong","description":"","frontmatter":{},"headers":[],"relativePath":"en/problemler.md","filePath":"en/problemler.md"}'),n={name:"en/problemler.md"};function d(s,t,l,h,i,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Situation</th><th>What to do</th></tr></thead><tbody><tr><td>Blank white screen / &quot;A screen error occurred&quot;</td><td><strong>Reload</strong>, or close the window and open it again. Sales are not lost.</td></tr><tr><td>&quot;Product not found&quot;</td><td>This product is not in the system — the admin should <a href="./mallar.html">add it</a>.</td></tr><tr><td>The scanner does not read</td><td>Check the scanner cable. Scan into Notepad: digits should appear. If the barcode is torn or worn — type the name to search.</td></tr><tr><td>The printer does not print</td><td><a href="./printerler.html#problemler">Printer → Problems</a>.</td></tr><tr><td>I forgot my password</td><td>The admin should set a new one in <a href="./istifadeciler.html">Users</a>. If the admin forgot theirs — contact your technical person.</td></tr><tr><td>&quot;Too many failed attempts&quot;</td><td>Wait 1 minute or ask the admin to press <strong>Unlock</strong>.</td></tr><tr><td>The program does not open, shows an error</td><td>Take a photo of the message and send it to your technical person.</td></tr><tr><td>The <strong>Recovery</strong> screen opened</td><td><a href="./backup.html#berpa-ekrani">Backup and restore → Recovery screen</a>. The recovery code is needed.</td></tr><tr><td>Red &quot;Database damage detected&quot;</td><td>You can keep selling. Tell your technical person soon — a restore from the latest backup may be needed.</td></tr><tr><td>Yellow &quot;Backups are not reaching Telegram&quot;</td><td><a href="./telegram.html">Telegram</a>.</td></tr><tr><td>&quot;The computer clock is wrong&quot;</td><td>Fix the date and time in Windows (so sales don&#39;t get the wrong date).</td></tr><tr><td>Uninstall/update says &quot;Kassa is currently running&quot;</td><td>Close the Kassa window, wait 2 seconds, <strong>OK</strong>.</td></tr><tr><td>The computer broke</td><td><a href="./backup.html#komputer-xarab-oldu">Backup → The computer broke</a>.</td></tr></tbody></table><h2 id="showing-the-problem-to-the-developer" tabindex="-1">Showing the problem to the developer <a class="header-anchor" href="#showing-the-problem-to-the-developer" aria-label="Permalink to &quot;Showing the problem to the developer&quot;">​</a></h2><p>Click your name at the bottom left → <strong>Report a problem</strong> → <strong>Download file</strong> (or <strong>Send to Telegram</strong>) → send the file via WhatsApp/Telegram. The file does <strong>not</strong> contain sales or prices.</p>',4)])])}const g=e(n,[["render",d]]);export{m as __pageData,g as default};
